import {ArenaSoundEffects} from '/src/js/toy-room/ArenaSoundEffects.js';
import {createAudioSystem} from '/src/js/audio.js';
export async function run(){
 const data=await(await fetch('/docs/diario-ia/qa/auditoria-audio-20261022/execucao.json')).json();
 const duration=data.resumo.duracaoReal+2,offline=new OfflineAudioContext(2,Math.ceil(duration*44100),44100),native=window.AudioContext;
 let virtualTime=0;const loads=[];
 const originalPreload=ArenaSoundEffects.prototype.preload;
 ArenaSoundEffects.prototype.preload=function(c){const p=originalPreload.call(this,c);if(p)loads.push(p);return p;};
 const proxy=new Proxy(offline,{get(target,key){if(key==='currentTime')return virtualTime;if(key==='state')return 'running';const v=target[key];if(typeof v!=='function')return v;if(key.startsWith('create'))return (...args)=>{const node=v.apply(target,args);if(node.disconnect)node.disconnect=()=>{};if(node.stop){const stop=node.stop.bind(node);node.stop=t=>stop(t??virtualTime);}return node;};return v.bind(target);}});
 window.AudioContext=function(){return proxy;};
 const audio=createAudioSystem();audio.initAudio();await Promise.all(loads);ArenaSoundEffects.prototype.preload=originalPreload;window.AudioContext=native;
 const events=data.eventos.filter(e=>e.etapa==='batalha-completa');const victory=events.findLast(e=>e.event==='victory');const origin=victory.tempo-data.resumo.duracaoReal;
 const schedule=[...events.map(e=>({at:e.tempo-origin,event:e.event})),...data.batidas.filter(e=>e.etapa==='batalha-completa').map(e=>({at:e.tempo-origin,beat:e.beat}))].sort((a,b)=>a.at-b.at);
 for(const event of schedule){virtualTime=Math.max(0,event.at);if(event.event)audio.playArenaSound(event.event);else audio.playArenaMusicBeat(event.beat);}
 const music=await offline.decodeAudioData(await(await fetch('/assets/audio/Circular%20Dissonance%20(1).mp3')).arrayBuffer());const source=offline.createBufferSource(),gain=offline.createGain();source.buffer=music;source.loop=true;gain.gain.value=.812;source.connect(gain);gain.connect(offline.destination);source.start(0,Math.max(0,data.frames[0].musica-data.frames[0].t));
 const rendered=await offline.startRendering();let peak=0,sum=0,clipped=0;for(let c=0;c<2;c++)for(const v of rendered.getChannelData(c)){peak=Math.max(peak,Math.abs(v));sum+=v*v;if(Math.abs(v)>1)clipped++;}
 const boundaries=[];for(const threshold of [.025,.01,.001,.0001]){let first=music.length,last=0;for(let c=0;c<music.numberOfChannels;c++){const d=music.getChannelData(c);for(let i=0;i<d.length;i++)if(Math.abs(d[i])>threshold){first=Math.min(first,i);last=Math.max(last,i);}}boundaries.push({limiar:threshold,inicioMs:1000*first/music.sampleRate,caudaMs:1000*(music.length-last-1)/music.sampleRate,intervaloNaEmendaMs:1000*(first+music.length-last-1)/music.sampleRate});}
 // Compara os transientes do arquivo com os da batida sintética: não atribui BPM definitivo.
 return {resumo:{eventos:events.length,batidas:schedule.filter(e=>e.beat!==undefined).length,duracaoRenderizada:duration,metodo:'Reconstrução offline dos mesmos eventos medidos na partida, incluindo interrupções de canais, amostras, síntese original, percussão e música em volume 0,812; fase da música aproximada pela telemetria. Não é captura do alto-falante.'},mixagem:{pico:peak,rms:Math.sqrt(sum/(rendered.length*2)),amostrasAcimaDe1:clipped,headroomDb:-20*Math.log10(peak)},emendaMusical:boundaries};
}
